package com.ianblk.zianmanager;
import com.google.gson.JsonObject;
import net.minecraft.server.level.ServerPlayer;
import java.util.*;
public final class CenteredZoneSmoke {
 public static void verify(ManagerRuntime runtime,ServerPlayer player)throws Exception{var server=player.server;server.getPlayerList().op(player.getGameProfile());var here=player.blockPosition().below();var f=new JsonObject();f.addProperty("id","smoke_centered");f.addProperty("enabled",false);f.addProperty("team","");f.addProperty("radiusX",3);f.addProperty("radiusZ",3);f.addProperty("above",6);f.addProperty("below",0);runtime.request(player,"zone",runtime.store().data().zones().containsKey("smoke_centered")?"smoke_centered":"");act(runtime,player,"center",f);var zone=runtime.store().data().zones().get("smoke_centered");if(zone==null || zone.center()==null || zone.center().x()!=here.getX() || zone.center().y()!=here.getY() || zone.second().x()-zone.first().x()+1!=7)throw new IllegalStateException("Zone creation did not use current floor block / 7x7 radius");var center=zone.center();player.moveTo(player.getX()+2,player.getY(),player.getZ()+1,0,0);f.addProperty("radiusX",5);f.addProperty("radiusZ",4);f.addProperty("above",8);f.addProperty("below",2);runtime.request(player,"zone","smoke_centered");act(runtime,player,"resize",f);zone=runtime.store().data().zones().get("smoke_centered");if(!zone.center().equals(center) || zone.second().x()-zone.first().x()+1!=11 || zone.second().z()-zone.first().z()+1!=9)throw new IllegalStateException("Zone resize moved its anchor or used wrong dimensions");runtime.cancel("smoke_centered");if(!runtime.store().data().zones().get("smoke_centered").center().equals(center))throw new IllegalStateException("Cancellation discarded zone center");var sessions=ManagerRuntime.class.getDeclaredField("sessions");sessions.setAccessible(true);((Map<?,?>)sessions.get(runtime)).remove(player.getUUID());server.getPlayerList().deop(player.getGameProfile());ZianManager.LOGGER.info("Zian Manager centered zone smoke passed: floor anchor, radius3=7x7, resize and preserved center");}
 private static void act(ManagerRuntime runtime,ServerPlayer player,String op,JsonObject fields)throws Exception{var sf=ManagerRuntime.class.getDeclaredField("sessions");sf.setAccessible(true);var session=((Map<?,?>)sf.get(runtime)).get(player.getUUID());var method=session.getClass().getDeclaredMethod("token");method.setAccessible(true);runtime.action(player,new ManagerNetwork.Action((UUID)method.invoke(session),op,fields.toString()));}
}
